package com.hospital.smartqueue.doctor.scheduling.infrastructure; import com.hospital.smartqueue.doctor.scheduling.domain.DoctorLeave; import org.springframework.data.jpa.repository.*; import java.time.*; import java.util.*; public interface DoctorLeaveRepository extends JpaRepository<DoctorLeave,UUID>{ @Query("select l from DoctorLeave l where l.doctorId=:d and l.branchId=:b and l.startDate<=:to and l.endDate>=:from") List<DoctorLeave> findOverlapping(UUID d,UUID b,LocalDate from,LocalDate to); }
